/* Demonstrates sync() and syncfs(2) calls */
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>

int main(void) {
    const char *path = "/tmp/data_to_flush.txt";
    int fd;

    // 1. Demonstrate system-wide sync
    printf("\n--- Global sync() ---\n");
    printf("Scheduling all pending I/O across all filesystems.\n");
    sync(); // Returns void, always successful in scheduling.
    printf("Global sync complete.\n");

    // 2. Demonstrate filesystem-specific syncfs
    printf("\n--- syncfs() on specific filesystem ---\n");

    // Open a file. This file sits on the filesystem we want to flush.
    fd = open(path, O_RDWR | O_CREAT, 0644);
    if (fd == -1) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    // Write some data (which is likely sitting only in the kernel buffer cache)
    if (write(fd, "Persistent data line.\n", 21) == -1) {
        perror("Failed to write data");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Attempting syncfs on file descriptor %d...\n", fd);

    // Commit all pending data for the filesystem containing 'fd'
    if (syncfs(fd) == -1) {
        // Error handling for syncfs
        fprintf(stderr, "syncfs failed: %s (Error code %d)\n", strerror(errno), errno);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("syncfs successful: Data persistence confirmed on target filesystem.\n");

    close(fd);
    unlink(path);
    return EXIT_SUCCESS;
}
